arguments.command:
cd /app && cat > app/assets/javascripts/quizzy.js <<'EOF'
(function () {
  "use strict";

  function initOptionRows() {
    var container = document.getElementById("option-rows");
    var addButton = document.getElementById("add-option");
    if (!container || !addButton) return;

    function createOptionRow(index) {
      var row = document.createElement("div");
      row.className = "option-row";
      row.setAttribute("data-option-row", "");

      row.innerHTML =
        '<div class="option-row__field">' +
          '<label class="option-text-label" for="question_options_' + index + '_text">Option ' + (index + 1) + '</label>' +
          '<input class="input option-text-input" type="text" name="question[options][' + index + '][text]" id="question_options_' + index + '_text" placeholder="Option text" autocomplete="off">' +
        '</div>' +
        '<div class="option-row__correct">' +
          '<input type="hidden" name="question[options][' + index + '][correct]" value="0" class="option-correct-hidden">' +
          '<input type="checkbox" name="question[options][' + index + '][correct]" id="question_options_' + index + '_correct" value="1" class="option-correct-input">' +
          '<label class="option-correct-label" for="question_options_' + index + '_correct">Option ' + (index + 1) + ' is correct</label>' +
        '</div>' +
        '<button type="button" class="btn btn--danger btn--icon" data-remove-option aria-label="Remove option">✕</button>';

      return row;
    }

    function reindexOptionRows() {
      var rows = Array.prototype.slice.call(container.querySelectorAll("[data-option-row]"));

      rows.forEach(function (row, index) {
        var textInput = row.querySelector(".option-text-input");
        var hiddenCorrect = row.querySelector(".option-correct-hidden");
        var checkbox = row.querySelector(".option-correct-input");
        var textLabel = row.querySelector(".option-text-label");
        var correctLabel = row.querySelector(".option-correct-label");

        if (!textInput || !hiddenCorrect || !checkbox || !textLabel || !correctLabel) return;

        var number = index + 1;
        textInput.name = "question[options][" + index + "][text]";
        textInput.id = "question_options_" + index + "_text";
        hiddenCorrect.name = "question[options][" + index + "][correct]";
        checkbox.name = "question[options][" + index + "][correct]";
        checkbox.id = "question_options_" + index + "_correct";

        textLabel.htmlFor = textInput.id;
        textLabel.textContent = "Option " + number;
        correctLabel.htmlFor = checkbox.id;
        correctLabel.textContent = "Option " + number + " is correct";
      });

      container.dataset.nextIndex = String(rows.length);
    }

    addButton.addEventListener("click", function () {
      var index = container.querySelectorAll("[data-option-row]").length;
      var row = createOptionRow(index);
      container.appendChild(row);
      reindexOptionRows();
      var input = row.querySelector(".option-text-input");
      if (input) input.focus();
    });

    container.addEventListener("click", function (event) {
      var removeButton = event.target.closest("[data-remove-option]");
      if (!removeButton) return;

      var row = removeButton.closest("[data-option-row]");
      if (row) row.remove();
      reindexOptionRows();
    });

    reindexOptionRows();
  }

  function initPreview() {
    var root = document.querySelector("[data-preview-root]");
    if (!root) return;

    var questions = Array.prototype.slice.call(root.querySelectorAll("[data-preview-question]"));
    var result = root.querySelector("[data-preview-result]");
    var scoreText = root.querySelector("[data-preview-score-text]");
    var startOverButton = document.getElementById("preview-start-over");

    if (questions.length === 0) return;

    var score = 0;

    function showQuestion(index) {
      questions.forEach(function (question, questionIndex) {
        question.hidden = questionIndex !== index;
      });
      if (result) result.hidden = true;
    }

    function showResult() {
      questions.forEach(function (question) {
        question.hidden = true;
      });
      if (result) result.hidden = false;
      if (scoreText) scoreText.textContent = "Score: " + score + "/" + questions.length;
    }

    function resetPreview() {
      score = 0;

      questions.forEach(function (question) {
        question.hidden = true;
        question.dataset.answered = "false";

        var optionsContainer = question.querySelector(".play-options");
        if (optionsContainer) {
          optionsContainer.classList.remove("is-locked", "is-revealed");
        }

        Array.prototype.slice.call(question.querySelectorAll("[data-preview-option]")).forEach(function (option) {
          option.disabled = false;
          option.classList.remove("is-picked", "is-correct");
          var mark = option.querySelector(".play-option__mark");
          if (mark) mark.hidden = true;
        });

        var status = question.querySelector("[data-preview-status]");
        if (status) {
          status.hidden = true;
          status.textContent = "";
          status.classList.remove("play-status--right", "play-status--wrong");
        }

        var nextButton = question.querySelector("[data-preview-next]");
        var scoreButton = question.querySelector("[data-preview-score]");
        if (nextButton) nextButton.hidden = true;
        if (scoreButton) scoreButton.hidden = true;
      });

      if (result) result.hidden = true;
      showQuestion(0);
    }

    questions.forEach(function (question, questionIndex) {
      var optionsContainer = question.querySelector(".play-options");
      var options = Array.prototype.slice.call(question.querySelectorAll("[data-preview-option]"));
      var status = question.querySelector("[data-preview-status]");
      var nextButton = question.querySelector("[data-preview-next]");
      var scoreButton = question.querySelector("[data-preview-score]");
      var isLastQuestion = questionIndex === questions.length - 1;

      options.forEach(function (option) {
        option.addEventListener("click", function () {
          if (question.dataset.answered === "true") return;
          question.dataset.answered = "true";

          var pickedCorrect = option.dataset.correct === "true";
          if (pickedCorrect) score += 1;

          if (optionsContainer) optionsContainer.classList.add("is-locked", "is-revealed");

          options.forEach(function (candidate) {
            candidate.disabled = true;
            if (candidate.dataset.correct === "true") {
              candidate.classList.add("is-correct");
              var mark = candidate.querySelector(".play-option__mark");
              if (mark) mark.hidden = false;
            }
          });

          option.classList.add("is-picked");

          if (status) {
            status.textContent = pickedCorrect ? "Correct!" : "Wrong!";
            status.classList.remove("play-status--right", "play-status--wrong");
            status.classList.add(pickedCorrect ? "play-status--right" : "play-status--wrong");
            status.hidden = false;
          }

          if (nextButton) nextButton.hidden = isLastQuestion;
          if (scoreButton) scoreButton.hidden = !isLastQuestion;
        });
      });

      if (nextButton) {
        nextButton.addEventListener("click", function () {
          showQuestion(questionIndex + 1);
        });
      }

      if (scoreButton) {
        scoreButton.addEventListener("click", showResult);
      }
    });

    if (startOverButton) {
      startOverButton.addEventListener("click", resetPreview);
    }

    showQuestion(0);
  }

  document.addEventListener("DOMContentLoaded", function () {
    initOptionRows();
    initPreview();
  });
})();
EOF
