/* ---------- Quizzy application additions ---------- */

[hidden] { display: none !important; }

.admin-header__logo { text-decoration: none; }
.admin-header__logo:hover { color: var(--c-pink); }

.question-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
  list-style: none;
  padding: 0;
  margin: 0;
}

.question-list > li { list-style: none; }
.question-list .card { margin-bottom: 0; }
.question-item__actions { min-width: 220px; }
.question-item__actions .buttons { justify-content: flex-end; }
.question-item__actions .active-toggle { margin: 0; }
.active-toggle .checkbox { justify-content: flex-end; }

.option-actions { margin-bottom: 28px; }
.option-row { align-items: end; }
.option-row__field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.option-row__correct {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 0.65em;
}
.option-row__field label,
.option-row__correct label {
  font-size: 15px;
  font-weight: 600;
}
.option-row__field .input { min-width: 0; }

.preview-banner { border-radius: var(--radius); margin-bottom: 24px; }
.preview-banner .buttons { gap: 16px; }
.preview-banner .buttons a { font-weight: 600; }
.preview-play {
  min-height: auto;
  max-width: 760px;
  padding: 24px 0 60px;
}
.preview-question-actions { margin-top: 20px; }
.result-card {
  background: var(--c-white);
  border-radius: var(--radius);
  padding: clamp(32px, 7vw, 72px) 24px;
}
.result-card h2 { margin-bottom: 0.6em; }

