  .question-item__actions .buttons,
  .active-toggle .checkbox { justify-content: flex-start; }
  .option-row { grid-template-columns: 1fr; align-items: stretch; }
  .option-row__correct { padding-bottom: 0; flex-wrap: wrap; }
  .option-row > .btn { justify-self: start; }
}
